"""Embedded guide image assets and full-screen image viewer.

Provides 100% self-contained image data for the User Guide, immune to missing file paths in frozen exe.
"""

from __future__ import annotations

from PySide6.QtCore import QByteArray, Qt
from PySide6.QtGui import QCursor, QPixmap
from PySide6.QtWidgets import (
    QDialog,
    QHBoxLayout,
    QLabel,
    QPushButton,
    QScrollArea,
    QVBoxLayout,
    QWidget,
)

# Base64 encoded JPEG diagrams (1376x768 HD)
_IMAGES_B64: dict[str, str] = {
    "step1": "",
    "step2": "",
    "step3": "",
    "wizard": "",
    "rules": "",
}

_CACHE: dict[str, QPixmap] = {}


def get_guide_pixmap(key: str) -> QPixmap:
    """Load guide illustration QPixmap from embedded Base64 data."""
    if key in _CACHE:
        return _CACHE[key]

    b64_str = _IMAGES_B64.get(key, "")
    if not b64_str:
        return QPixmap()

    raw = QByteArray.fromBase64(QByteArray(b64_str.encode("ascii")))
    pix = QPixmap()
    pix.loadFromData(raw, "JPEG")
    _CACHE[key] = pix
    return pix


class ImageZoomDialog(QDialog):
    """Cửa sổ xem ảnh hướng dẫn kích thước đầy đủ (Full Resolution Zoom Viewer)."""

    def __init__(self, key: str, title: str, parent: QWidget | None = None) -> None:
        super().__init__(parent)
        self.setWindowTitle(f"Chi Tiết Ảnh: {title}")
        self.resize(1100, 720)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(10)

        # Header bar
        hbar = QHBoxLayout()
        lbl_title = QLabel(f"<b>{title}</b> — Kích thước gốc: 1376 × 768 px")
        lbl_title.setStyleSheet("font-size: 13px; color: #1e293b;")
        hbar.addWidget(lbl_title)
        hbar.addStretch(1)

        btn_close_top = QPushButton("X Đóng", self)
        btn_close_top.setFixedHeight(30)
        btn_close_top.clicked.connect(self.accept)
        hbar.addWidget(btn_close_top)
        layout.addLayout(hbar)

        # Scrollable image viewer
        scroll = QScrollArea(self)
        scroll.setWidgetResizable(True)
        scroll.setStyleSheet("background: #0f172a; border: 1px solid #334155;")

        lbl_img = QLabel()
        lbl_img.setAlignment(Qt.AlignCenter)
        pix = get_guide_pixmap(key)
        if not pix.isNull():
            lbl_img.setPixmap(pix)
        else:
            lbl_img.setText(f"[Không thể tải ảnh {key}]")
            lbl_img.setStyleSheet("color: #ef4444; font-size: 14px;")

        scroll.setWidget(lbl_img)
        layout.addWidget(scroll, 1)

        # Bottom bar
        bbar = QHBoxLayout()
        lbl_tip = QLabel("Mẹo: Dùng thanh cuộn để xem toàn bộ chi tiết rõ nét.")
        lbl_tip.setStyleSheet("font-size: 12px; color: #64748b;")
        bbar.addWidget(lbl_tip)
        bbar.addStretch(1)

        btn_close = QPushButton("Đóng", self)
        btn_close.setFixedHeight(32)
        btn_close.setMinimumWidth(100)
        btn_close.clicked.connect(self.accept)
        bbar.addWidget(btn_close)
        layout.addLayout(bbar)


class ClickableGuideImage(QWidget):
    """Widget ảnh minh họa có thể nhấp chuột để phóng to toàn màn hình."""

    def __init__(self, key: str, title: str, display_width: int = 820, parent: QWidget | None = None) -> None:
        super().__init__(parent)
        self.key = key
        self.title = title

        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 4, 0, 8)
        layout.setSpacing(4)

        # Image label
        self.lbl_img = QLabel()
        self.lbl_img.setAlignment(Qt.AlignCenter)
        self.lbl_img.setCursor(QCursor(Qt.PointingHandCursor))
        self.lbl_img.setStyleSheet(
            "background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 4px; padding: 4px;"
        )

        pix = get_guide_pixmap(key)
        if not pix.isNull():
            scaled = pix.scaledToWidth(display_width, Qt.SmoothTransformation)
            self.lbl_img.setPixmap(scaled)
        else:
            self.lbl_img.setText(f"[Ảnh: {title}]")

        self.lbl_img.mousePressEvent = self._on_clicked
        layout.addWidget(self.lbl_img)

        # Zoom caption button
        cbar = QHBoxLayout()
        cbar.addStretch(1)
        btn_zoom = QPushButton(f"[+] Xem kích thước lớn 1376×768 ({title})", self)
        btn_zoom.setFixedHeight(26)
        btn_zoom.setCursor(QCursor(Qt.PointingHandCursor))
        btn_zoom.setStyleSheet(
            "QPushButton { font-size: 11px; color: #0284c7; background: #f0f9ff; border: 1px solid #bae6fd; border-radius: 3px; padding: 2px 10px; }"
            "QPushButton:hover { background: #e0f2fe; color: #0369a1; border-color: #7dd3fc; }"
        )
        btn_zoom.clicked.connect(self._open_zoom)
        cbar.addWidget(btn_zoom)
        cbar.addStretch(1)
        layout.addLayout(cbar)

    def _on_clicked(self, event) -> None:
        self._open_zoom()

    def _open_zoom(self) -> None:
        dlg = ImageZoomDialog(self.key, self.title, self.window())
        dlg.exec()
